const folders = $input.all();
const results = [];
for (const item of folders) {
  const f = item.json;
  if (f.mimeType && f.mimeType !== 'application/vnd.google-apps.folder') continue;
  if (!f.id) continue;
  results.push({
    json: {
      barcodeFolderId: f.id,
      barcodeName: f.name || f.id
    }
  });
}
return results;

const files = $input.all();
const folderId = $('Loop Barcode Folders').item.json.barcodeFolderId;
const barcodeName = $('Loop Barcode Folders').item.json.barcodeName;

const byName = {};
for (const item of files) {
  const f = item.json;
  if (f && f.name) byName[f.name] = f;
}

const getFile = (suffix) => {
  return Object.values(byName).find(f => {
    const name = (f.name || '').trim();
    return new RegExp(`(^|\\s|-)${suffix}\\.png$`, 'i').test(name);
  });
};

const sareeFile = getFile('5');
const blouseFile = getFile('6');
const existing2 = getFile('2');
const existing3 = getFile('3');

const hasSaree = !!sareeFile;
const hasBlouseFabric = !!blouseFile;

let missingReason = '';
if (!hasSaree && !hasBlouseFabric) missingReason = 'Missing 5.png and 6.png';
else if (!hasSaree) missingReason = 'Missing 5.png';
else if (!hasBlouseFabric) missingReason = 'Missing 6.png';

return [{
  json: {
    barcodeFolderId: folderId,
    barcodeName: barcodeName,
    hasSaree,
    hasBlouseFabric,
    hasRequiredImages: hasSaree && hasBlouseFabric,
    sareeFileId: sareeFile ? sareeFile.id : null,
    blouseFabricFileId: blouseFile ? blouseFile.id : null,
    existing2PngId: existing2 ? existing2.id : null,
    existing3PngId: existing3 ? existing3.id : null,
    missingReason
  }
}];

const v = $json;
return [{
  json: {
    barcodeFolderId: v.barcodeFolderId,
    barcodeName: v.barcodeName,
    errorReason: v.missingReason,
    errorType: 'Missing Source Image',
    failedNode: 'Map & Validate Images',
    failedAt: new Date().toISOString()
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.errorLog) staticData.errorLog = [];
for (const item of $input.all()) {
  staticData.errorLog.push(item.json);
}
return $input.all();

const item = $input.item;
const binaryKey = Object.keys(item.binary || {})[0] || 'data';
const binaryData = item.binary[binaryKey];
const context = $('Map & Validate Images').item.json;

return {
  json: {
    ...context,
    blouseFabricBase64: binaryData.data,
    blouseFabricMimeType: binaryData.mimeType || 'image/png'
  }
};

const item = $input.item;
const err = item.json.error || item.json;
const message = (typeof err === 'string') ? err : (err.message || JSON.stringify(err));
const statusCode = (item.json.error && (item.json.error.httpCode || item.json.error.statusCode)) || null;
const lower = (message || '').toLowerCase();

let errorType = 'Network Error';
if (statusCode === 429 || lower.includes('rate limit') || lower.includes('quota')) {
  errorType = 'Rate Limit';
} else if (lower.includes('safety') || lower.includes('blocked') || lower.includes('policy')) {
  errorType = 'Safety Block';
} else if (lower.includes('json') || lower.includes('parse')) {
  errorType = 'Invalid JSON';
} else if (lower.includes('image') && (lower.includes('process') || lower.includes('decode'))) {
  errorType = 'Image Processing Error';
}

const v = $('Map & Validate Images').item.json;

return {
  json: {
    barcodeFolderId: v.barcodeFolderId,
    barcodeName: v.barcodeName,
    errorReason: message,
    errorType,
    failedNode: 'Generate Stitched Blouse (Gemini)',
    failedAt: new Date().toISOString()
  }
};

const context = $('Map & Validate Images').item.json;

const binaryKey = Object.keys($input.item.binary || {})[0];

if (!binaryKey) {
  return {
    json: {
      ...context,
      hasGeneratedBlouseImage: false,
      blouseExtractionError: 'No binary image returned by Gemini'
    }
  };
}

const binary = $input.item.binary[binaryKey];

return {
  json: {
    ...context,
    hasGeneratedBlouseImage: true,
    blouseGeneratedBase64: binary.data,
    blouseGeneratedMimeType: binary.mimeType || 'image/png'
  },
  binary: {
    data: binary
  }
};

const v = $input.item.json;
const reason = v.blouseExtractionError || 'Unknown extraction error';
const lower = reason.toLowerCase();
const errorType = (lower.includes('safety') || lower.includes('block')) ? 'Safety Block' : 'Invalid JSON';

return {
  json: {
    barcodeFolderId: v.barcodeFolderId,
    barcodeName: v.barcodeName,
    errorReason: reason,
    errorType,
    failedNode: 'Extract Generated Blouse Image',
    failedAt: new Date().toISOString()
  }
};

const context = $('Map & Validate Images').item.json;
const blouseGen = $('Extract Generated Blouse Image').item.json;

return {
  json: {
    ...context,
    blouseGeneratedBase64: blouseGen.blouseGeneratedBase64,
    blouseGeneratedMimeType: blouseGen.blouseGeneratedMimeType
  }
};

